import React from 'react';
import { Box, Typography, Stack, Paper } from '@mui/material';

type Member = {
  id: number;
  citizenId: string;
  fullName: string;
  email: string;
};

type LoanData = {
  createdAt: string;
  endDate: string;
  id: number;
  installmentAmount: number;
  installmentCount: number;
  installmentFrequency: number;
  interestRate: number;
  loanAmount: number;
  member: Member;
  memberId: number;
  note: string;
  price: number;
  productId: number;
  productName: string;
  remainingDebt: number;
  startDate: string;
  status: string;
  updatedAt: string | null;
};

const loanData: LoanData = {
  createdAt: "2025-10-04T12:41:02.17337Z",
  endDate: "2025-10-05T00:00:00Z",
  id: 39,
  installmentAmount: 65650,
  installmentCount: 1,
  installmentFrequency: 0,
  interestRate: 1,
  loanAmount: 65000,
  member: {
    id: 1,
    citizenId: "91630020",
    fullName: "Akkdach Narach",
    email: "akkdach@gmail.com",
  },
  memberId: 1,
  note: "",
  price: 65000,
  productId: 12,
  productName: "ไอโฟน 17 Pro, ไอโฟน 17 Pro Max",
  remainingDebt: 0,
  startDate: "2025-10-04T00:00:00Z",
  status: "Pending",
  updatedAt: null,
};

const LoanDetail: React.FC = () => {
  return (
    <Box p={2}>
      <Paper elevation={3} sx={{ p: 2, borderRadius: 2 }}>
        <Stack spacing={1}>
          <Typography variant="h6" fontWeight="bold">
            สินเชื่อ #{loanData.id}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            สถานะ: {loanData.status}
          </Typography>

          <Typography variant="subtitle1" mt={2}>
            สินค้า: {loanData.productName}
          </Typography>
          <Typography>ราคา: ฿{loanData.price.toLocaleString()}</Typography>
          <Typography>ยอดกู้: ฿{loanData.loanAmount.toLocaleString()}</Typography>
          <Typography>ดอกเบี้ย: {loanData.interestRate}%</Typography>
          <Typography>ยอดผ่อน/เดือน: ฿{loanData.installmentAmount.toLocaleString()}</Typography>
          <Typography>จำนวนงวด: {loanData.installmentCount}</Typography>

          <Typography variant="subtitle2" mt={2}>
            วันที่เริ่มต้น: {new Date(loanData.startDate).toLocaleDateString()}
          </Typography>
          <Typography>วันที่สิ้นสุด: {new Date(loanData.endDate).toLocaleDateString()}</Typography>

          <Typography variant="subtitle2" mt={2}>
            ผู้กู้: {loanData.member.fullName}
          </Typography>
          <Typography>อีเมล: {loanData.member.email}</Typography>
          <Typography>เลขบัตรประชาชน: {loanData.member.citizenId}</Typography>
        </Stack>
      </Paper>
    </Box>
  );
};

export default LoanDetail;
